// Multi5Script.cpp -- reconstruction of a shipped mission script.
//
// The Academy wave-survival mode: twenty-six waves of droids, scaled by player count,
// with pickups and a bonus item dropped on a path between waves. 9,552 bytes of code
// over 28 KB of .rodata and 11 KB of .data, all of it rebuilt from the shipped bytes
// (tools/dis_func.py, tools/gen_mission_data.py) and checked against them
// (tools/sbs_diff.py, tools/verify_missions.py).
//
// Three things about this TU that the small multiplayer stubs never exercised:
//
//   1. The tuning tables are reached as BARE OFFSETS off the section base --
//      `addi r0, r4, 0x55bc` with no relocation -- so the whole of .rodata and .data
//      has to be reproduced byte for byte, in declaration order, or nothing matches.
//      tools/gen_mission_data.py generates the declarations and audits the order.
//   2. That only works with `-str readonly`, which puts string literals in .rodata
//      instead of .data. Without it the literals interleave with the pointer tables
//      in .data and every offset in the file moves.
//   3. The four `<N>PlayerInit` functions each carry their own copy of all 26 waves,
//      named `Wave1Enemies`, `Wave1Enemies_2`, `_3`, `_4` in the shipped symbol table.
//      The `_N` suffixes are in the original source, not added here: `Multi17Script`
//      does the same thing inside a `namespace multi17Names`. The unsuffixed set is
//      the one-player table, and the four sets are declared 1P, 2P, 3P, 4P -- the
//      reverse of the order the functions that use them appear in .text.

namespace MissionUtility
{
    void  SetMusicLooping(bool loop);
    void  PlayMusic(const char *name, bool loop);
    int   StartSound(const char *name, bool loop, float volume, float fadeIn,
                     float fadeOut, const char *bus, int flags, const char *tag);
    int   AddObjective(const char *text);
    void  SetEnemiesOneWay(int a, int b);
    void  SetMapZoom(float in, float out);
    void  PreloadConfig(const char *odf);

    int   MPGetNumPlayers();
    int   MPGetNumLivePlayers();
    bool  MPHasGameStarted();
    int   MPGetWave();
    void  MPSetWave(int wave);
    bool  MPIsGladiatorRound();
    void  MPStartGladiatorRound();
    void  MPSpawnPointItemOnPath(const char *path, float delay, int a, int b);

    float GetTime();
    float GetRandomFloat(float lo, float hi);
    bool  IsAlive(int handle);

    int   AddAmmoBox(const char *odf, int a, float b);
    int   AddHealthBox(const char *odf, int a, float b);

    int   CreateObject(const char *odf, const char *where, const char *team,
                       int a, int b, int c);
    float GetMaxHealth(int handle);
    float GetMaxShield(int handle);
    void  SetMaxHealth(int handle, float v);
    void  SetMaxShield(int handle, float v);
    void  SetCurHealth(int handle, float v);
    void  SetCurShield(int handle, float v);
    void  Goto(int handle, const char *path, int a);
    void  SetQueueFlag(bool on);
    void  Patrol(int handle, const char *path, float speed, bool loop);
}

extern "C" {
    void *memset(void *dst, int c, unsigned long n);
    char *strcpy(char *dst, const char *src);
    int   strcmp(const char *a, const char *b);
}

// ---------------------------------------------------------------------------------------
// The three table shapes. Each is pinned by how the code reads it: `lhzx` then a split
// into two signed bytes for the enemy list, `lfsx` for the wait times, and a 20-byte
// structure copy onto the stack for the bonus pickups.
// ---------------------------------------------------------------------------------------

struct Enemy
{
    char odf;                   // index into ENEMY_ODFS
    char spawn;                 // index into SpawnPoints / GotoPaths
};

struct SpaceFruit
{
    float minDelay;
    float maxDelay;
    int   a;
    int   b;
    char  path;                 // index into BonusPaths; 0 means "no bonus this step"
};

// ---------------------------------------------------------------------------------------
// The mission's tuning data, in the shipped declaration order. Generated by
// tools/gen_mission_data.py, which reads it back out of the binary; do not reorder or
// resize anything here without re-running the ordering audit.
// ---------------------------------------------------------------------------------------

