// literal @655 created here: "Multi5Script"

// literal @658 created here: "SPMission"

// literal @770 created here: "EP2_V1_T03_01"

// literal @771 created here: "AmbThule_Asteroid01_lp"

// literal @774 created here: "multiplayer.types.academy.rule01"

// literal @775 created here: "multiplayer.types.academy.rule02"

// literal @776 created here: "multiplayer.types.academy.rule03"


// The shipped pool has "Multi5Script" at .rodata+0x6c78 and "SPMission" at +0x6c88,
// immediately after the last wave table and immediately before Execute's own literals.
// They are the RTTI class names, but CodeWarrior emits RTTI at end-of-TU, which would
// put them last; something in the original header created them here. These two statics
// are the same stand-in used in probes/src/Multi12Script.cpp, moved to where this TU
// needs them. Without them every literal in Execute is 0x1c low -- "Multi5Script"
// padded to 16 plus "SPMission" padded to 12. ("DLLBase" is eight bytes with its
// terminator, so it goes to .sdata2 and leaves no hole in .rodata.)
static const char *const kClassName = "Multi5Script";
static const char *const kBaseName  = "SPMission";

// ---------------------------------------------------------------------------------------
// The classes.
//
// DLLBase declares no data, so its vptr sits at offset 0 -- CodeWarrior otherwise places
// the vptr after the members. SPMission's four (base, count) pairs occupy +0x04..+0x23
// and the derived members start at +0x24. See analysis/mission_script_abi.md.
// ---------------------------------------------------------------------------------------

class DLLBase
{
public:
    // Six vtable slots, read out of __vt__7DLLBase (0x8035ae5c, 24 B) and
    // __vt__9SPMission (0x8035ae3c, 32 B) -- see analysis/mission_script_abi.md.
    // A script never calls its own virtuals, so getting this wrong left every byte of
    // .text intact; it is .data that catches it -- tools/verify_vtables.py.
    virtual ~DLLBase() {}                 // +0x08
    virtual void InitialSetup();          // +0x0c  DLLBase::InitialSetup, 4 B, blr
    virtual bool Load();                  // +0x10  DLLBase::Load, 8 B, `return true`
    virtual void Execute();               // +0x14  DLLBase::Execute, 4 B, blr
};

class SPMission : public DLLBase
{
public:
    SPMission();
    virtual ~SPMission() {}                       // +0x08
    // SPMission::InitialSetup (0x801887b8, 200 B) zeroes the bool block, fills the float
    // block with 99999.0f, zeroes both int blocks, and only then calls slot +0x18 -- this
    // script's Setup. So a mission's start state is defined: every latch Setup does not
    // mention is false on the first tick.
    virtual void InitialSetup();                  // +0x0c  overrides DLLBase's
    virtual void Execute() = 0;                   // +0x14  re-declared pure; slot is null
    virtual void Setup() = 0;                     // +0x18  first slot SPMission adds
    virtual void RestartMission(int);             // +0x1c  0x801885bc, 4 B, blr

    bool  *mBools;    int mBoolCount;    // +0x04 +0x08
    int   *mIntsB;    int mCountB;       // +0x0c +0x10
    int   *mIntsC;    int mCountC;       // +0x14 +0x18
    void  *mBlockD;   int mCountD;       // +0x1c +0x20
};

// One row of the wave schedule: 32 bytes, indexed in Execute by `slwi rN, wave, 5`.
// Every table is a parallel array indexed by the step within the wave.
struct Wave
{
    int                  count;              // +0x00  steps in this wave
    const Enemy         *enemies;            // +0x04  NUL-group-separated
    const float         *waitTimes;          // +0x08
    const char         **sounds;             // +0x0c
    const SpaceFruit    *spaceFruits;        // +0x10
    const bool          *dontWaitForDead;    // +0x14
    const char         **healthPacks;        // +0x18
    const char         **ammoPacks;          // +0x1c
};

class Multi5Script : public SPMission
{
public:
    virtual ~Multi5Script();

    Multi5Script()
    {
        mBoolCount = 3;    mBools  = &mDone;
        mCountB    = 4;    mIntsB  = &mUnusedB;
        mCountC    = 32;   mIntsC  = &mUnusedC;
        mCountD    = 8;    mBlockD = &mStep;
    }

    virtual void Setup();
    virtual void Execute();

    void SpawnEnemies(int wave, int step);

    // ---- the per-step work, as inline members -------------------------------------
    //
    // These four are the same `(int wave, int step)` shape as SpawnEnemies. That is not a
    // stylistic choice, it is what the shipped register allocation says. Written inline in
    // Execute -- even with the wave and step copied into locals -- the scaled wave index
    // outranks the loop counter and the two swap registers: 49 words adrift with the
    // instruction stream otherwise identical, and no amount of reordering, sharing or
    // `register` fixes it. As parameters of a helper they rank the other way round and
    // Execute is exact. SpawnEnemies is the one member of the family big enough that
    // CodeWarrior emitted it out of line instead of inlining it.

    void GiveAmmo(int wave, int step)
    {
        if (wave >= 0 && wave < 30 && step >= 0 && step < mWaves[wave].count) {
            // The pickup tables are one flat list per wave, split into per-step groups by
            // NUL entries: walk forward over `step` separators, then hand out everything
            // up to the next one.
            int i = 0;
            int n = i;
            while (n < step) {
                if (!mWaves[wave].ammoPacks[i]) {
                    n++;
                }
                i++;
            }
            while (mWaves[wave].ammoPacks[i]) {
                MissionUtility::AddAmmoBox(mWaves[wave].ammoPacks[i], 0, -1.0f);
                i++;
            }
        }
    }

    void GiveHealth(int wave, int step)
    {
        if (wave >= 0 && wave < 30 && step >= 0 && step < mWaves[wave].count) {
            int i = 0;
            int n = i;
            while (n < step) {
                if (!mWaves[wave].healthPacks[i]) {
                    n++;
                }
                i++;
            }
            while (mWaves[wave].healthPacks[i]) {
                MissionUtility::AddHealthBox(mWaves[wave].healthPacks[i], 0, -1.0f);
                i++;
            }
        }
    }

    void DropBonus(int wave, int step)
    {
        if (wave >= 0 && wave < 30 && step >= 0 && step < mWaves[wave].count) {
            SpaceFruit fruit = mWaves[wave].spaceFruits[step];
            if (fruit.path) {
                // GetRandomFloat runs first: CodeWarrior evaluates `a + b` right to left,
                // so this is the spelling that calls it before GetTime.
                mBonusTime = MissionUtility::GetTime()
                           + MissionUtility::GetRandomFloat(fruit.minDelay,
                                                            fruit.maxDelay);
                mBonusA = fruit.a;
                mBonusB = fruit.b;
                strcpy(mBonusPath, BonusPaths[fruit.path]);
            }
        }
    }

    void OnePlayerInit();
    void TwoPlayerInit();
    void ThreePlayerInit();
    void FourPlayerInit();

    Wave   mWaves[30];                       // +0x024  memset to zero in Setup
    const unsigned char *mIncrements;        // +0x3e4  how far MPSetWave jumps per wave
    bool   mUnusedLatch;                     // +0x3e8
    bool   mDone;                            // +0x3e9  the one-shot latch
    bool   mWaiting;                         // +0x3ea  counting down to the next step
    bool   mDontWaitForDead;                 // +0x3eb  step overlaps the previous one
    char   mPad3ec[8];                       // +0x3ec
    int    mUnusedB;                         // +0x3f4  registered, never read
    float  mSpawnDelay;                      // +0x3f8  wait time of the current step
    float  mNextSpawn;                       // +0x3fc
    float  mBonusTime;                       // +0x400  < 0 means "no bonus pending"
    int    mPad404[2];                       // +0x404
    int    mUnusedC;                         // +0x40c  registered, never read
    int    mHandles[30];                     // +0x410  live enemies
    int    mPad488;                          // +0x488
    int    mPad48c[2];                       // +0x48c
    int    mStep;                            // +0x494
    int    mWave;                            // +0x498
    int    mPad49c[2];                       // +0x49c
    int    mNumPlayers;                      // +0x4a4
    int    mBonusA;                          // +0x4a8
    int    mBonusB;                          // +0x4ac
    int    mRounds;                          // +0x4b0
    int    mPad4b4;                          // +0x4b4
    char   mBonusPath[32];                   // +0x4b8            -> sizeof == 0x4d8
};

// ---------------------------------------------------------------------------------------

Multi5Script::~Multi5Script()
{
}

void Multi5Script::Execute()
{
    if (!mDone) {
        MissionUtility::SetMusicLooping(true);
        MissionUtility::PlayMusic("EP2_V1_T03_01", true);
        MissionUtility::StartSound("AmbThule_Asteroid01_lp", true,
                                   1.0f, 0.0f, 0.0f, "", 0, "");

        MissionUtility::AddObjective("multiplayer.types.academy.rule01");
        MissionUtility::AddObjective("multiplayer.types.academy.rule02");
        MissionUtility::AddObjective("multiplayer.types.academy.rule03");

        MissionUtility::SetEnemiesOneWay(1, 8);
        MissionUtility::SetMapZoom(900.0f, 10000000.0f);
        mDone = true;

        // Each player count gets its own copy of all 26 waves.
        mNumPlayers = MissionUtility::MPGetNumPlayers();
        switch (mNumPlayers) {
        case 1:  OnePlayerInit();   break;
        case 2:  TwoPlayerInit();   break;
        case 3:  ThreePlayerInit(); break;
        case 4:  FourPlayerInit();  break;
        }
        mBonusTime = -1.0f;
    }

    if (!MissionUtility::MPHasGameStarted()) {
        return;
    }

    if (mWaiting) {
        if (mNextSpawn < MissionUtility::GetTime()) {
            mDontWaitForDead = false;
            SpawnEnemies(mWave, mStep);

            GiveAmmo(mWave, mStep);

            GiveHealth(mWave, mStep);

            DropBonus(mWave, mStep);

            if (mWave >= 0 && mWave < 30 && mStep >= 0 && mStep < mWaves[mWave].count) {
                mDontWaitForDead = mWaves[mWave].dontWaitForDead[mStep];
                mSpawnDelay = mWaves[mWave].waitTimes[mStep];
                if (mWaves[mWave].sounds[mStep]
                    && MissionUtility::MPGetWave() <= 20
                    && (!MissionUtility::MPIsGladiatorRound()
                        || MissionUtility::MPGetNumLivePlayers() >= 2)) {
                    // Not looping, unlike the ambience started above. This block stays
                    // written out: as a helper it would be inlined too and the function
                    // grows -- only the three above take parameters in the shipped code.
                    MissionUtility::StartSound(mWaves[mWave].sounds[mStep], false,
                                               1.0f, 0.0f, 0.0f, "", 0, "");
                }
            }

            if (mWave >= 0 && mWave < 30) {
                if (mStep >= mWaves[mWave].count - 1) {
                    mWave++;
                    MissionUtility::MPSetWave(mIncrements[mWave - 1]
                                              + MissionUtility::MPGetWave());
                    mStep = -1;
                }
            } else if (mWave == 30) {
                // Past the last wave: reset and count another lap.
                mBonusTime  = -1.0f;
                mSpawnDelay = 0.0f;
                mNextSpawn  = -1.0f;
                mStep = -1;
                mWave = 0;
                mRounds++;
            }
            mStep++;
            mWaiting = false;
        }
    } else {
        // A step normally waits for everything it spawned to die. The `goto` is the
        // shape the shipped code has: `mDontWaitForDead` branches straight past the
        // sweep to the gladiator check, and a live enemy leaves through the same exit
        // as the rest of the function. Folding that into a flag costs an extra
        // register and a redundant `li`.
        int i;
        if (!mDontWaitForDead) {
            for (i = 0; i < 30; i++) {
                if (mHandles[i] && !MissionUtility::IsAlive(mHandles[i])) {
                    mHandles[i] = 0;
                }
            }
            // `&=`, not `&&`: the shipped loop has no branch in it, just
            // cntlzw/srwi to turn "handle is zero" into 0 or 1 and an `and`. Spelling
            // it `allDead = allDead & ...` re-normalises the bool every iteration.
            bool allDead = true;
            for (i = 0; i < 30; i++) {
                allDead &= (mHandles[i] == 0);
            }
            if (!allDead) {
                goto bonus;
            }
        }
        if (!MissionUtility::MPIsGladiatorRound()) {
            mNextSpawn = mSpawnDelay + MissionUtility::GetTime();
            mWaiting = true;
        }
    }

bonus:
    if (mBonusTime > 0.0f && MissionUtility::GetTime() > mBonusTime) {
        if (mWave > 0 && mWave % 26 == 0) {
            MissionUtility::MPSpawnPointItemOnPath(mBonusPath, 0.1f, mBonusB, mBonusA);
        } else {
            MissionUtility::MPSpawnPointItemOnPath(mBonusPath, 50.0f, mBonusB, mBonusA);
        }
        mBonusTime = -1.0f;
    }
}

void Multi5Script::SpawnEnemies(int wave, int step)
{
    // Written as one guarded block rather than four early returns: the shipped code
    // branches straight out of the last test (`bge` to the epilogue), which is what the
    // `&&` chain produces. An early `return` costs an extra unconditional branch.
    if (wave >= 0 && wave < 30 && step >= 0 && step < mWaves[wave].count) {

    // Same grouping as the pickups: skip `step` NUL separators, then spawn the run.
    int i = 0;
    int n = 0;
    while (n < step) {
        if (!ENEMY_ODFS[mWaves[wave].enemies[i].odf]) {
            n++;
        }
        i++;
    }

    // `obj` before `slot`: the shipped code keeps the spawned handle in r28 and the
    // free-slot cursor in r27, and the allocator hands out the callee-saved registers
    // in declaration order. Swapping the two declarations swaps the two registers and
    // costs 22 words.
    int obj;
    int slot = 0;
    while (ENEMY_ODFS[mWaves[wave].enemies[i].odf]) {
        Enemy e = mWaves[wave].enemies[i];
        i++;

        if (strcmp(ENEMY_ODFS[e.odf], "GLADIATOR") == 0) {
            MissionUtility::MPStartGladiatorRound();
            continue;
        }

        while (mHandles[slot]) {
            slot++;
        }

        if (slot < 30) {
            obj = mHandles[slot] = MissionUtility::CreateObject(ENEMY_ODFS[e.odf],
                                                               SpawnPoints[e.spawn],
                                                               "enemy", 5, -1, -1);
        } else {
            obj = MissionUtility::CreateObject(ENEMY_ODFS[e.odf],
                                               SpawnPoints[e.spawn],
                                               "enemy", 5, -1, -1);
        }

        // Every twenty waves the droids come back tougher.
        int tier = (MissionUtility::MPGetWave() - 1) / 20;
        if (tier) {
            float health = MissionUtility::GetMaxHealth(obj);
            float shield = MissionUtility::GetMaxShield(obj);
            float scale  = 0.5f * tier + 1.0f;
            health *= scale;
            shield *= scale;
            MissionUtility::SetMaxHealth(obj, health);
            MissionUtility::SetMaxShield(obj, shield);
            MissionUtility::SetCurHealth(obj, health);
            MissionUtility::SetCurShield(obj, shield);
        }

        MissionUtility::Goto(obj, GotoPaths[e.spawn], 0);

        // Which factory this spawn point belongs to: four blocks of eight, plus the
        // single big-guy spawn.
        switch (e.spawn) {
        case 0: case 1: case 2: case 3: case 4: case 5: case 6: case 7:
            MissionUtility::SetQueueFlag(true);
            MissionUtility::Patrol(obj, PatrolPaths[1], 40.0f, true);
            MissionUtility::SetQueueFlag(false);
            break;
        case 8: case 9: case 10: case 11: case 12: case 13: case 14: case 15:
            MissionUtility::SetQueueFlag(true);
            MissionUtility::Patrol(obj, PatrolPaths[2], 40.0f, true);
            MissionUtility::SetQueueFlag(false);
            break;
        case 16: case 17: case 18: case 19: case 20: case 21: case 22: case 23:
            MissionUtility::SetQueueFlag(true);
            MissionUtility::Patrol(obj, PatrolPaths[3], 40.0f, true);
            MissionUtility::SetQueueFlag(false);
            break;
        case 24: case 25: case 26: case 27: case 28: case 29: case 30: case 31:
            MissionUtility::SetQueueFlag(true);
            MissionUtility::Patrol(obj, PatrolPaths[4], 40.0f, true);
            MissionUtility::SetQueueFlag(false);
            break;
        case 32:
            MissionUtility::SetQueueFlag(true);
            MissionUtility::Patrol(obj, PatrolPaths[5], 40.0f, true);
            MissionUtility::SetQueueFlag(false);
            break;
        }
    }

    }
}

