void Multi5Script::Setup()
{
    // One `i` for both loops, not one per loop: the shipped code keeps the counter in
    // r31 across the memset, which is what a single function-scope variable gets. Two
    // scoped `i`s put the first loop's counter in a volatile register instead.
    int i;

    mDone = false;
    mSpawnDelay = 0.0f;
    mNextSpawn = -1.0f;
    mWaiting = false;
    mStep = 0;
    mWave = 0;

    for (i = 0; i < 30; i++) {
        mHandles[i] = 0;
    }
    memset(mWaves, 0, sizeof(mWaves));

    for (i = 0; i < 13; i++) {
        if (ENEMY_ODFS[i]) {
            MissionUtility::PreloadConfig(ENEMY_ODFS[i]);
        }
    }
    mRounds = 0;
}

SPMission *Multi5BuildMission()
{
    return new Multi5Script();
}
